## Layer 1: The Complete `rtk-prerewrite.js` Script

Location: `%USERPROFILE%\.claude\scripts\rtk-prerewrite.js`

```javascript
#!/usr/bin/env node
// rtk-prerewrite.js — PreToolUse hook: auto-prefix all Bash commands with `rtk`.
// Platform: Windows native Node.js (no Bash dependency).
// Contract: read JSON from stdin, write JSON to stdout if command was modified.
// Empty stdout = passthrough (Claude Code treats empty output as no change).

'use strict';

// Shell built-ins and trivial commands that produce no meaningful output
// and gain nothing from RTK. RTK would forward them unchanged anyway,
// but prepending `rtk ` would look wrong in logs.
const EXEMPT = new Set([
  'echo', 'printf', 'pwd', 'whoami', 'cd', 'pushd', 'popd',
  'source', '.', 'export', 'unset', 'set', 'env',
  'true', 'false', 'exit', 'return', 'break', 'continue',
  '[', 'test', 'if', 'while', 'for', 'do', 'done', 'fi',
  'then', 'else', 'elif', 'case', 'esac', 'function',
  'read', 'wait', 'sleep', 'kill', 'exec', 'eval',
  'mkdir', 'rmdir', 'rm', 'mv', 'cp', 'touch', 'chmod', 'chown',
  'type', 'which', 'where',
]);

// RTK's own meta commands: already RTK, never re-prefix.
// Also matches any `rtk <subcommand>` via the startsWithRtk check below.
const RTK_META = new Set([
  'rtk',
]);

/**
 * Determine whether a single command segment should be prefixed.
 * A "segment" is text between `&&`, `||`, or `;` (not inside pipes —
 * pipe continuations are not standalone commands for RTK purposes).
 *
 * @param {string} seg  Trimmed segment text
 * @returns {string}    Segment, possibly prefixed with 'rtk '
 */
function processSegment(seg) {
  const trimmed = seg.trim();

  // Empty segment (e.g., trailing ; or leading &&)
  if (!trimmed) return seg;

  // RTK_DISABLED env-var prefix — honour the escape hatch, skip the segment
  if (trimmed.startsWith('RTK_DISABLED=1')) return seg;

  // Shell variable assignment at the start (VAR=value command) — extract
  // leading assignments and apply the rule to the actual command word.
  // e.g., "SKIP_ENV=1 tsc" → "SKIP_ENV=1 rtk tsc"
  // e.g., "FOO=bar BAZ=qux git status" → "FOO=bar BAZ=qux rtk git status"
  let prefix = '';
  let rest = trimmed;
  // Match zero or more `IDENTIFIER=...` tokens at the front
  const assignRe = /^([A-Z_][A-Z0-9_]*=[^\s]*\s+)*/i;
  const assignMatch = rest.match(assignRe);
  if (assignMatch && assignMatch[0]) {
    prefix = assignMatch[0];
    rest = rest.slice(prefix.length).trim();
    if (!rest) return seg; // pure env assignment, no command
  }

  // Already prefixed with rtk
  if (rest.startsWith('rtk ') || rest === 'rtk') return seg;

  // Extract the command word (first token, ignoring any leading ! or -)
  const cmdWord = rest.split(/\s+/)[0].replace(/^[!-]+/, '');

  // Exempt set
  if (EXEMPT.has(cmdWord)) return seg;

  // Shell redirections / subshell starters — don't touch
  if (cmdWord === '(' || cmdWord === '{' || cmdWord === ')' || cmdWord === '}') return seg;

  // Reconstruct with rtk prefix, preserving any leading env assignments
  // and the original whitespace of the overall segment
  const leading = seg.match(/^\s*/)[0];
  const trailing = seg.match(/\s*$/)[0];
  return leading + prefix + 'rtk ' + rest + trailing;
}

/**
 * Split a command string by && / || / ; while respecting:
 * - Quoted strings (single and double quotes)
 * - Subshells: $(...) and `...`
 * - Pipes (|): do NOT split — pipe continuations are not standalone commands
 *
 * Returns an array of {text, sep} objects where sep is the delimiter that
 * followed this token ('' for the last token).
 */
function splitByLogicalOperators(cmd) {
  const tokens = [];
  let cur = '';
  let i = 0;
  while (i < cmd.length) {
    const ch = cmd[i];

    // Single-quoted string: no escaping inside
    if (ch === "'") {
      let j = i + 1;
      while (j < cmd.length && cmd[j] !== "'") j++;
      cur += cmd.slice(i, j + 1);
      i = j + 1;
      continue;
    }

    // Double-quoted string
    if (ch === '"') {
      let j = i + 1;
      while (j < cmd.length && cmd[j] !== '"') {
        if (cmd[j] === '\\') j++; // skip escaped char
        j++;
      }
      cur += cmd.slice(i, j + 1);
      i = j + 1;
      continue;
    }

    // Backtick subshell
    if (ch === '`') {
      let j = i + 1;
      while (j < cmd.length && cmd[j] !== '`') j++;
      cur += cmd.slice(i, j + 1);
      i = j + 1;
      continue;
    }

    // $(...) subshell — not splitting inside
    if (ch === '$' && cmd[i + 1] === '(') {
      let depth = 0;
      let j = i;
      while (j < cmd.length) {
        if (cmd[j] === '(') depth++;
        else if (cmd[j] === ')') { depth--; if (depth === 0) { j++; break; } }
        j++;
      }
      cur += cmd.slice(i, j);
      i = j;
      continue;
    }

    // && operator
    if (ch === '&' && cmd[i + 1] === '&') {
      tokens.push({ text: cur, sep: '&&' });
      cur = '';
      i += 2;
      continue;
    }

    // || operator
    if (ch === '|' && cmd[i + 1] === '|') {
      tokens.push({ text: cur, sep: '||' });
      cur = '';
      i += 2;
      continue;
    }

    // Pipe | (single) — do NOT split, treat as continuation of same segment
    // (RTK is not applied to the pipe RHS; it's a filter, not a command)
    if (ch === '|') {
      cur += ch;
      i++;
      continue;
    }

    // Semicolon ;
    if (ch === ';') {
      tokens.push({ text: cur, sep: ';' });
      cur = '';
      i++;
      continue;
    }

    cur += ch;
    i++;
  }
  // Final token
  tokens.push({ text: cur, sep: '' });
  return tokens;
}

/**
 * Main: rewrite the command string.
 * Returns the rewritten string, or null if no change was needed.
 */
function rewriteCommand(cmd) {
  const tokens = splitByLogicalOperators(cmd);
  let changed = false;
  const rewritten = tokens.map(({ text, sep }) => {
    const newText = processSegment(text);
    if (newText !== text) changed = true;
    return { text: newText, sep };
  });

  if (!changed) return null;

  return rewritten.map(({ text, sep }) => text + sep).join('');
}

// --- Entry point ---

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => { input += chunk; });
process.stdin.on('end', () => {
  try {
    const payload = JSON.parse(input);

    // Only intercept Bash tool calls
    if (payload.tool_name !== 'Bash') {
      process.exit(0);
    }

    const originalCommand = (payload.tool_input && payload.tool_input.command) || '';
    if (!originalCommand) process.exit(0);

    const rewritten = rewriteCommand(originalCommand);
    if (rewritten === null) {
      // No change needed — empty stdout = passthrough
      process.exit(0);
    }

    // Output the modified_input JSON
    process.stdout.write(JSON.stringify({ modified_input: { command: rewritten } }));
    process.exit(0);
  } catch (e) {
    // Parse error or unexpected shape — fail silently, passthrough
    process.exit(0);
  }
});
```

